package com.example.orderdesk.security;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.List;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;

class CurrentUserTest {

  @AfterEach
  void clear() {
    SecurityContextHolder.clearContext();
  }

  private void login(String id, String role) {
    SecurityContextHolder.getContext().setAuthentication(
        new UsernamePasswordAuthenticationToken(id, null, List.of(new SimpleGrantedAuthority("ROLE_" + role))));
  }

  @Test
  void ownerIsAllowed() {
    login("3", "CUSTOMER");
    assertThatCode(() -> CurrentUser.requireOwnerOrAdmin(3L)).doesNotThrowAnyException();
  }

  @Test
  void otherCustomerIsRefused() {
    login("4", "CUSTOMER");
    assertThatThrownBy(() -> CurrentUser.requireOwnerOrAdmin(3L)).isInstanceOf(AccessDeniedException.class);
  }

  @Test
  void adminIsAllowedForAnyCustomer() {
    login("admin-1", "ADMIN");
    assertThatCode(() -> CurrentUser.requireOwnerOrAdmin(3L)).doesNotThrowAnyException();
  }
}
